<template>
  <div class="space-y-6">
    <CPageHeader :title="profile ? `Hola, ${profile.name.split(' ')[0]}` : 'Mis estancias'" description="Tus reservas, pagos y comprobantes, en un solo lugar."><NuxtLink to="/portal/book" class="btn btn-primary">Reservar habitación</NuxtLink></CPageHeader>
    <p v-if="error" class="operation-error" role="alert">{{ error }} <button class="underline" @click="load">Volver a intentar</button></p>
    <div class="guest-welcome"><div><p class="guest-eyebrow">TU PRÓXIMA VISITA</p><template v-if="nextStay"><h2>{{ nextStay.status==='checked_in'?'Disfruta tu estancia':'Te esperamos pronto' }}</h2><p>Habitación {{ nextStay.room_number }} · {{ formatDateOnly(nextStay.check_in) }} al {{ formatDateOnly(nextStay.check_out) }}</p><NuxtLink :to="`/portal/reservations/${nextStay.id}`">Ver mi reserva <span aria-hidden="true">→</span></NuxtLink></template><template v-else><h2>Un espacio para tus viajes</h2><p>{{ loading?'Estamos consultando tus estancias…':'Consulta tu historial o contacta con el hotel para organizar tu próxima visita.' }}</p></template></div><Icon name="system-uicons:home" class="welcome-icon" aria-hidden="true" /></div>
    <CCard>
      <div class="operation-heading"><div><h2>Mis reservas</h2><p class="guest-muted">{{ total }} {{ total===1?'reserva vinculada a tu cuenta':'reservas vinculadas a tu cuenta' }}</p></div><label class="guest-filter">Estado <select v-model="status" class="operation-filter" :disabled="loading" @change="page=1;loadReservations()"><option value="">Todas</option><option value="confirmed">Confirmadas</option><option value="checked_in">En estancia</option><option value="checked_out">Finalizadas</option><option value="cancelled">Canceladas</option></select></label></div>
      <p v-if="loading" role="status" class="guest-muted">Cargando tus reservas…</p>
      <div v-else-if="reservations.length" class="guest-reservations"><article v-for="r in reservations" :key="r.id" class="guest-reservation"><div><p class="guest-muted">Reserva #{{ r.id }} · {{ states[r.status] }}</p><h3>{{ r.room_type_name }} · Habitación {{ r.room_number }}</h3><p>{{ formatDateOnly(r.check_in) }} — {{ formatDateOnly(r.check_out) }}</p></div><div class="guest-reservation-total"><strong>{{ money(r.total_price) }}</strong><span>{{ r.status==='cancelled'?'Reserva cancelada':`Saldo pendiente: ${money(Math.max(0,Number(r.total_price)-Number(r.paid_amount)))}` }}</span><NuxtLink :to="`/portal/reservations/${r.id}`">Ver detalles</NuxtLink></div></article></div>
      <CEmptyState v-else title="Sin reservas para mostrar" description="Si esperabas encontrar una estancia, contacta con recepción para revisar su vinculación." />
      <div class="operation-pager"><CButton variant="secondary" :disabled="page===1||loading" @click="page--;loadReservations()">Anterior</CButton><span>{{ page }} / {{ Math.max(1,pages) }}</span><CButton variant="secondary" :disabled="page>=pages||loading" @click="page++;loadReservations()">Siguiente</CButton></div>
    </CCard>
    <CHotelPresentation />
    <div class="guest-contact"><div><h2>Estamos para ayudarte</h2><p>Reserva tu próxima visita desde el portal. Solicita cambios de fechas o cancelaciones desde el detalle de tu reserva.</p></div><div><p v-if="hotel.settings.value.phone">{{ hotel.settings.value.phone }}</p><p v-if="hotel.settings.value.email">{{ hotel.settings.value.email }}</p><p>Entrada desde {{ hotel.settings.value.check_in_time.slice(0,5) }} · Salida hasta {{ hotel.settings.value.check_out_time.slice(0,5) }}</p></div></div>
  </div>
</template>
<script setup lang="ts">
import type { PortalProfile,PortalReservation } from '~/types/portal'
import { formatDateOnly } from '~/utils/dates'
definePageMeta({layout:'guest',middleware:'auth'})
const portal=useCustomerPortal(),{run,error,loading,states}=portal,hotel=useHotelSettings(),{money}=hotel
const profile=ref<PortalProfile>(),reservations=ref<PortalReservation[]>([]),nextStay=ref<PortalReservation>(),status=ref(''),page=ref(1),pages=ref(1),total=ref(0)
const fetchReservations=async()=>{const r=await portal.reservations(page.value,status.value);reservations.value=r.data||[];pages.value=r.pagination.totalPages;total.value=r.pagination.total}
const loadReservations=()=>run(fetchReservations)
const load=()=>run(async()=>{await Promise.all([fetchReservations(),portal.profile().then(r=>{profile.value=r.data}),portal.nextStay().then(r=>{nextStay.value=r.data||undefined})])})
onMounted(load)
</script>
<style scoped>
.guest-welcome{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:32px;border:1px solid var(--border-color);border-radius:14px;background:var(--bg-secondary)}.guest-eyebrow{font-size:10px;letter-spacing:1.5px;color:#535ed6;font-weight:600;margin-bottom:12px}.guest-welcome h2{font-size:25px;font-weight:500;letter-spacing:-.6px;margin-bottom:10px}.guest-welcome p:not(.guest-eyebrow){color:var(--text-secondary);font-size:13px;line-height:1.8}.guest-welcome a{display:inline-block;color:#535ed6;font-size:12px;margin-top:20px}.welcome-icon{width:70px;height:70px;color:#a5acdf;flex-shrink:0}.guest-muted{font-size:12px;color:var(--text-secondary);margin-top:5px}.guest-filter{display:flex;align-items:center;gap:10px;font-size:12px}.guest-reservation{display:flex;justify-content:space-between;gap:24px;padding:24px 0;border-bottom:1px solid var(--border-color)}.guest-reservation h3{font-size:15px;font-weight:500;margin:8px 0}.guest-reservation p{font-size:12px;color:var(--text-secondary)}.guest-reservation-total{display:flex;flex-direction:column;gap:8px;text-align:right;justify-content:center}.guest-reservation-total strong{font-size:17px;font-weight:500}.guest-reservation-total span{font-size:11px;color:var(--text-secondary)}.guest-reservation-total a{font-size:12px;color:#535ed6}.guest-contact{display:flex;justify-content:space-between;gap:24px;padding:12px 0;font-size:12px;color:var(--text-secondary);line-height:1.9}.guest-contact h2{font-size:15px;color:var(--text-primary)}@media(max-width:640px){.guest-welcome{padding:24px}.welcome-icon{display:none}.guest-reservation{flex-direction:column;gap:14px}.guest-reservation-total{text-align:left}.guest-contact{flex-direction:column;gap:12px}}
</style>
